//! Item logic for Did It Last.
//!
//! Pure functions over plain data: no storage, no I/O. The wasm bindings below are what the
//! Vue app calls; the same functions can be lifted into a server later. Values cross the
//! boundary as typed objects (`Ts<T>`), with TypeScript types generated by tsify.

pub mod items;

use chrono::NaiveDate;
use tsify::{Ts, Tsify};
use wasm_bindgen::prelude::*;

use items::{Item, ItemProblem, ItemRow};

/// The core's crate version, so the app can show which build it is running.
#[wasm_bindgen(js_name = coreVersion)]
pub fn core_version() -> String {
    env!("CARGO_PKG_VERSION").to_string()
}

#[wasm_bindgen(js_name = itemRows)]
pub fn item_rows(items: Vec<Ts<Item>>, today: &str) -> Result<Vec<Ts<ItemRow>>, JsError> {
    let items = items
        .into_iter()
        .map(|i| i.to_rust())
        .collect::<Result<Vec<_>, _>>()?;
    items::item_rows(&items, parse_date(today)?)
        .into_iter()
        .map(|row| Ok(row.into_ts()?))
        .collect()
}

#[wasm_bindgen(js_name = itemProblem)]
pub fn item_problem(item: Ts<Item>) -> Result<Option<Ts<ItemProblem>>, JsError> {
    Ok(items::item_problem(&item.to_rust()?)
        .map(|p| p.into_ts())
        .transpose()?)
}

fn parse_date(date: &str) -> Result<NaiveDate, JsError> {
    date.parse()
        .map_err(|_| JsError::new(&format!("not a YYYY-MM-DD date: {date}")))
}
